func lawLine(fl *port.Cells, fw *port.Cells, et *port.Cells, page int32, y int32, cp int32) int32 {
	var start int32 = port.CellsLen(et)
	var line int32 = evidence.LnCount(fl)
	var word int32 = evidence.WdNew(fw, page, 50, y, 400, y+12, 50, y+12, 400, y+12, 0, 0, start, 1, line, 900, -1)
	port.CellsPush(et, cp)
	evidence.LnNew(fl, page, 50, y, 400, y+12, 50, y+12, 400, y+12, 0, 0, word, 1)
	return 0
}

func lawSeam(emonT *testing.T, capture int32, born int32, strong int32, middle int32, clip int32, expectedDrop int32, expectedKind int32) int32 {
	var fl *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	var ol *port.Cells = port.NewCells()
	var decisions *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var i int32 = 0
	var r int32 = 0
	model.PageNew(pages, 1, 450, 1000, 0, model.PkImage())
	model.PageNew(pages, 2, 450, 1000, 0, model.PkImage())
	port.CellsPush(mask, 1)
	port.CellsPush(mask, 1-born)
	lawLine(fl, fw, et, 1, 400, 81)
	lawLine(fl, fw, et, 2, 295, 32)
	for i < strong {
		if i == 2 {
			lawLine(fl, fw, et, 1, 500+(20*i), 45)
			lawLine(fl, fw, et, 2, 300+(20*i), 61)
		}
		lawLine(fl, fw, et, 1, 507+(20*i), 65+i)
		lawLine(fl, fw, et, 2, 307+(20*i), 65+i)
		i += 1
	}
	if middle == 1 {
		lawLine(fl, fw, et, 1, 600, 90)
	}
	if clip == 1 {
		r = evidence.OlNew(ol, 1, 50, 993, 400, 1000, 50, 993, 400, 993, 0, 0, -1, 0)
		evidence.OlSet(ol, r, evidence.OlfConf(), 300)
	}
	lawLine(fl, fw, et, 2, 400, 82)
	port.AssertEq(emonT, seams.MsRun(2, capture, mask, pages, ol, et, fl, fw, port.NewCells(), port.NewCells(), ledger, text, decisions, port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells()), expectedDrop, "rows dropped")
	port.AssertEq(emonT, model.LedgerCount(ledger), expectedDrop, "dropped rows retained in ledger")
	if expectedKind == 0 {
		port.AssertEq(emonT, port.CellsLen(decisions), 0, "no seam on an ordinary break")
	} else {
		port.AssertEq(emonT, port.CellsAt(decisions, 2), expectedKind, "expected seam decision")
	}
	return 0
}

func TestStrongAnchoredSeamIgnoresWhitespaceAndDeduplicatesSeparators(emonT *testing.T) {
	lawSeam(emonT, 0, 0, 4, 0, 0, 5, 1)
}

func TestInteriorMatchIsNotASeam(emonT *testing.T) {
	lawSeam(emonT, 2, 0, 4, 1, 0, 0, 0)
}

func TestSingleCopyMatchIsAmbiguous(emonT *testing.T) {
	lawSeam(emonT, 2, 0, 1, 0, 0, 0, 2)
}

func TestCleanBreakAndClippedGap(emonT *testing.T) {
	lawSeam(emonT, 2, 0, 0, 0, 0, 0, 0)
	lawSeam(emonT, 2, 0, 0, 0, 1, 0, 3)
}

func TestScanModeAndBornDigitalPassThrough(emonT *testing.T) {
	lawSeam(emonT, 1, 0, 4, 0, 0, 0, 0)
	lawSeam(emonT, 2, 1, 4, 0, 0, 0, 0)
}

func TestPixelCorrelationNeedsContrastAndPositiveCovariance(emonT *testing.T) {
	var pixels *port.Cells = port.NewCells()
	port.CellsPush(pixels, 0)
	port.CellsPush(pixels, 128)
	port.CellsPush(pixels, 255)
	port.CellsPush(pixels, 60)
	port.CellsPush(pixels, 124)
	port.CellsPush(pixels, 188)
	port.CellsPush(pixels, 255)
	port.CellsPush(pixels, 128)
	port.CellsPush(pixels, 0)
	port.CellsPush(pixels, 180)
	port.CellsPush(pixels, 180)
	port.CellsPush(pixels, 180)
	port.AssertEq(emonT, seams.MsNcc(pixels, 0, 3, 3), 1, "same signal with different exposure")
	port.AssertEq(emonT, seams.MsNcc(pixels, 0, 6, 3), 0, "opposite signal")
	port.AssertEq(emonT, seams.MsNcc(pixels, 0, 9, 3), 0, "flat area cannot corroborate")
}
